assert s['subject']=='chemie' and s['strictComplete']==110 and s['denominator']==377 and not s['issues'];assert all(r['status']=='pass' for r in s['requiredChecks']) and receipt['actualExitCode']==0
oldset=set(plan['protectedCurrentStrict104GoalIds']);now=set(s['strictCompleteGoalIds']);assert oldset<=now and now-oldset==set(plan['expectedSafeNewScientificGoalIds']);assert HOLD not in now
