write(OWN/'native-strict-new-science-and-full-protection.actual.json',{'checkedAtUTC':datetime.now(timezone.utc).isoformat(),'strictCurrent104ProtectedWholeGoalObjects':[{'goalId':g,'wholeObjectExact':a[g]==b[g]} for g in sorted(oldset)],'futureStrict110GoalIds':s['strictCompleteGoalIds'],'exactSixNewScientificClosureCandidates':sorted(now-oldset),'existingContextRestorationOnly':['70b34ae7-4481-590c-9a02-516464750832'],'existing104LostIds':sorted(oldset-now),'actualNativeFutureDenominator':s['denominator'],'nativeRequiredChecks':s['requiredChecks'],'nativeIssues':s['issues'],'protectedOtherSubjectBaseline':{subject:{'strict':r['strictComplete'],'denominator':r['denominator'],'strictGoalIds':r['strictCompleteGoalIds']} for subject,r in other.items()},'allOtherRawRegistryEntriesUnchanged':True,'sixWholePRecordLinesAndProfilesExact':True,'wholeExistingM371DecisionsAnd55CardsRetained':True,'wholeExistingUnrelatedQA371RecordsRetained':True,'allHumanFieldsExactlyPreserved':True,'noNewHumanApprovalOrTrial':True,'confirmedSemanticSplitStillOpen':HOLD,'oldHeldGoalRetainedButNotANewScientificApproval':True,'standaloneSafeApplicationBlockedUntilActualSplitRemediation':True,'operativeNewScientificClosures':0,'operativeRestoredBindings':0,'operativeStrictNetIncrease':0,'activeWrites':0})
